lines_r={4,11}; lines_c={0,5,24}
def touches(r0,r1,c0,c1):
    rows=set(range(r0,r1+1)); cols=set(range(c0,c1+1))
    if rows & lines_r or cols & lines_c: return True
    # adjacency: shape one step from a line
    if (r0-1 in lines_r) or (r1+1 in lines_r): return True
    if (c0-1 in lines_c) or (c1+1 in lines_c): return True
    return False
for r0,r1,c0,c1 in shapes:
